package com.wansheng.visitor.guard;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/internal/guard")class GuardInternalQueryController{private final GuardRepository repo;private final String token;GuardInternalQueryController(GuardRepository r,@Value("${visitor.guard.internal-token}")String t){repo=r;token=t;}private void check(String t){if(token.isBlank()||!token.equals(t))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}@GetMapping("/records")List<GuardRecord>records(@RequestHeader(value="X-Internal-Token",required=false)String t){check(t);return repo.listAll();}@GetMapping("/audits")List<Map<String,Object>>audits(@RequestHeader(value="X-Internal-Token",required=false)String t){check(t);return repo.audits();}}
